import { mkdir, readFile, unlink, writeFile } from 'node:fs/promises';
import { dirname, resolve } from 'node:path';
import type { DocumentStorage } from '@server/constant/interface';

/** Private disk adapter. Keys are generated by the service, never accepted from a client. */
export function createDocumentStorage(
  directory = process.env.DOCUMENT_STORAGE_DIR ?? '.data/documents',
): DocumentStorage {
  function path(key: string) {
    return resolve(directory, key);
  }
  return {
    async put(key, bytes) {
      await mkdir(dirname(path(key)), { recursive: true });
      await writeFile(path(key), bytes, { flag: 'wx', mode: 0o600 });
    },
    async get(key) {
      try {
        return new Uint8Array(await readFile(path(key)));
      } catch (error) {
        if ((error as NodeJS.ErrnoException).code === 'ENOENT') {
          return null;
        }
        throw error;
      }
    },
    async remove(key) {
      await unlink(path(key)).catch((error: NodeJS.ErrnoException) => {
        if (error.code !== 'ENOENT') {
          throw error;
        }
      });
    },
  };
}
